</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>

using namespace std;

long long f[181], n, min_cost;

long long get_abs_value(long long x) {
    return x < 0 ? -x : x;
}

void dfs_search(int level, long long current_cost) {
    if (n == 0) {
        min_cost = min(min_cost, current_cost);
        return;
    }
    if (level == 0) return;

    for (int i = -10; i <= 10; ++i) {
        long long change = i * f[level];
        if (n + change > 0) {
            n += change;
            dfs_search(level - 1, current_cost + get_abs_value(i) * level);
            n -= change;
            break;
        }
    }
    for (int i = -10; i <= 10; ++i) {
        long long change = i * f[level];
        if (n + change == 0) {
            n += change;
            dfs_search(level - 1, current_cost + get_abs_value(i) * level);
            n -= change;
            break;
        }
    }
    for (int i = 10; i >= -10; --i) {
        long long change = i * f[level];
        if (n + change < 0) {
            n += change;
            dfs_search(level - 1, current_cost + get_abs_value(i) * level);
            n -= change;
            break;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    f[1] = 1;
    for (int i = 2; i <= 16; ++i) {
        f[i] = f[i - 1] * 10 + 1;
    }
    min_cost = LLONG_MAX;
    dfs_search(16, 0);
    cout << min_cost << "\n";
    return 0;
}
